ee:message.ee:set-payload:
%dw 2.0
output application/json skipNullOn = "everywhere"
var notificationMethod = (vars.parameters.NOTIFICATION_METHOD default "") as String
var notificationValue  = (vars.parameters.NOTIFICATION_VALUE default "")
---
{
	basePath: p("bot-sapi.base-path"),
	host: p("bot-sapi.host"),
	port: p("bot-sapi.port"),
	method: "POST",
	path: p('bot-sapi.resources.services.base-path') ++ p('bot-sapi.resources.services.requestinvoice'),
	body: {
		"WSRequestHeader": {
			"System": {
				"name": vars.headers.name,
				"correlationID": vars.headers."X-CORRELATION-ID",
				"processingServer": ""
			},
			"Property": []
		},
		"WSRequestBody": {
			"Audit": {
				"Canal": vars.headers.name
			},
			"Bill": {
				"Number": (vars.parameters.BILLING_NUMBER default ""),
				"Period": ""
			},
			"Customer": {
				"Document_Number": (vars.filters.DocumentNumber default ""),
				"Document_Type": (vars.filters.DocumentType default "")
			},
			"Notify": {
				"Email": if ( upper(notificationMethod) == "EMAIL" ) notificationValue 
        else "",
				"Phone": if ( upper(notificationMethod) == "PHONE" ) notificationValue 
        else "",
				"Type": upper(notificationMethod)
			},
			"Service": {
				"Billing_Account": (vars.filters.BillingAccount default ""),
				"Phone": (vars.filters.Phone default "")
			}
		}
	},
	headers: vars.headers default {
	},
	queryParameters: {
	},
	uriParameters: {
	}
}

%dw 2.0
output application/json skipNullOn = "everywhere"
---
{
	basePath: p("bot-sapi.base-path"),
	host: p("bot-sapi.host"),
	port: p("bot-sapi.port"),
	method: "POST",
	path: p('bot-sapi.resources.services.base-path') ++ p('bot-sapi.resources.services.invoices'),
	body: {
		"WSRequestHeader": {
			"System": {
				"name": vars.headers.name,
				"correlationID": vars.headers."X-CORRELATION-ID",
				"processingServer": ""
			},
			"Property": []
		},
		"WSRequestBody": {
			"Audit": {
				"Canal": vars.headers.name
			},
			"Barcode": (vars.filters.Barcode default ""),
			"Billing_Account": (vars.filters.BillingAccount default ""),
			"Billing_Number": (vars.filters.BILLING_NUMBER default vars.parameters.BILLING_NUMBER default ""),
			"Phone": (vars.filters.Phone default ""),
		}
	},
	headers: vars.headers default {
	},
	queryParameters: {
	},
	uriParameters: {
	}
}

%dw 2.0
output application/json skipNullOn = "everywhere"
var billingInvoicePdfPath = if ( vars.billingOperation == "QUERY_BILL_PDF" ) p('zsmart-sapi.resources.queryBillPDF.path') else p('zsmart-sapi.resources.queryInvoicePDF.path')
---
{
	basePath: p("zsmart-sapi.base-path"),
	host: p("zsmart-sapi.host"),
	port: p("zsmart-sapi.port"),
	method: "GET",
	path: billingInvoicePdfPath,
	body: {
	},
	headers: vars.headers default {
	},
	queryParameters: {
		"transactionID": vars.transactionId,
		"invoiceType": vars.invoiceType,
		"invoiceNumber": vars.invoiceNumber,
		"accountNumber": vars.accountNumber,
		"comments": vars.comments
	},
	uriParameters: {
	}
}

%dw 2.0
output application/json
---
{
	basePath: p("mongo-db-sapi.base-path"),
	host: p("mongo-db-sapi.host"),
	port: p("mongo-db-sapi.port"),
	method: "POST",
	path: p('mongo-db-sapi.resources.dynamicQuery.base-path'),
	body: {
		"query": {
			"aggregate": "MDM_CUENTA_FACTURACION",
			"pipeline": [{
				"\$match": {
					"Tipo_Documento": vars.filters.'CUSTOMER_ID_TYPE',
					"Numero_Identificacion": vars.filters.'CUSTOMER_ID'
				}
			}],
			"cursor": {
			}
		}
	},
	headers: vars.headers default {
	},
	queryParameters: {
	},
	uriParameters: {
	}
}
